class Transport:
    def __init__(self, client):
        self.client = client

    def command(self, mapped_positions):
        """
        Move the robot to the given joint positions.

        :param mapped_positions: A dictionary mapping joint names to positions.
        """
        for joint_name, position in mapped_positions.items():
            if joint_name not in self.client.joint_mapping:
                raise NotImplementedError(f"Joint '{joint_name}' not supported by this SDK.")
            self.client.move_base(self.client.joint_mapping[joint_name], position)

    def get_state(self):
        """
        Get the current state of the robot.

        :return: A dictionary mapping joint names to positions.
        """
        return self.client.get_joint_positions()

    def stop(self):
        """
        Stop all motors.
        """
        self.client.stop()

    def disconnect(self):
        """
        Disconnect the client without moving any motors.
        """
        self.client.close()

